// ============================================================================
// Wishbone_apb: APB4 register wrapper around Wishbone_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/Wishbone.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/Wishbone.md
// ============================================================================
module Wishbone_apb #(
  parameter int DW = 32,
  parameter int AW = 32,
  parameter int DEPTH = 256
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  input logic cyc_i,
  input logic stb_i,
  input logic we_i,
  input logic [AW-1:0] adr_i,
  input logic [DW-1:0] dat_i,
  input logic [3:0] sel_i,
  input logic [2:0] cti_i,
  output logic [DW-1:0] dat_o,
  output logic ack_o,
  output logic stall_o,
  output logic err_o,
  output logic rty_o
);
  localparam logic [31:0] ID_VALUE = 32'h57420200;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [4:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd5) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic          c_irq;
  Wishbone_top #(.DW(DW), .AW(AW), .DEPTH(DEPTH)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .cyc_i(cyc_i),
    .stb_i(stb_i),
    .we_i(we_i),
    .adr_i(adr_i),
    .dat_i(dat_i),
    .sel_i(sel_i),
    .cti_i(cti_i),
    .dat_o(dat_o),
    .ack_o(ack_o),
    .stall_o(stall_o),
    .err_o(err_o),
    .rty_o(rty_o),
    .irq(c_irq)
  );

  // ---------------- registers ----------------
  logic [0:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[0:0] & wmask[0:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[0:0]) | (PWDATA[0:0] & wmask[0:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
    end
  end

  // ---------------- core inputs ----------------

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_irq;
  end
  assign irq = |(irq_status & irq_enable);

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd4: apb_rdata = scratch;
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
